def load_proxies():
    global PROXIES
    # Try external file first, fallback to embedded list
    _script_dir = os.path.dirname(os.path.abspath(__file__))
    _candidates = [
        os.path.join(_script_dir, "proxies.txt"),
        os.path.join(_script_dir, "proxy.txt"),
        os.path.join(_script_dir, "attached_assets", "proxy_1779557036411.txt"),
        "attached_assets/proxy_1779557036411.txt",
        "proxies.txt",
    ]
    for _path in _candidates:
        if os.path.exists(_path):
            with open(_path) as _f:
                _loaded = [l.strip() for l in _f if l.strip() and ":" in l]
            if _loaded:
                PROXIES = _loaded
                console.print(f"[green][+] Loaded [bold]{len(PROXIES)}[/bold] proxies from file[/green]")
                return
    PROXIES = list(EMBEDDED_PROXIES)
    console.print(f"[green][+] Using [bold]{len(PROXIES)}[/bold] embedded proxies[/green]")


def get_random_proxy():
    if PROXIES:
        proxy = random.choice(PROXIES)
        return {"http": f"http://{proxy}", "https": f"http://{proxy}"}
    return {}


