# ═══════════════════════════════════════════════════════════════
# MODULE 1 — فحص الشبكات (Network Scanner)
# ═══════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════
# MODULE 1 — Network Scanner
# ═══════════════════════════════════════════════════════════════

def module_network_scanner():
    show_banner()
    console.print(Panel(
        "[bold cyan][ 1 ] فحص الشبكات — Network Scanner[/bold cyan]\n"
        "[dim]تكتشف الأجهزة الحية على الشبكة وتعرض IP وHostname وزمن الاستجابة\n"
        "تستخدم TCP connect على المنافذ الشائعة + ICMP ping للكشف الكامل[/dim]",
        border_style="cyan"
    ))

    while True:
        console.print("\n[cyan]اختر العملية:[/cyan]")
        console.print("  [bold cyan][1][/bold cyan] Ping Scan          — [dim]اكتشاف الأجهزة الحية في نطاق IP[/dim]")
        console.print("  [bold cyan][2][/bold cyan] ARP Table          — [dim]عرض جدول ARP (الأجهزة المتصلة مؤخراً)[/dim]")
        console.print("  [bold cyan][3][/bold cyan] Traceroute         — [dim]تتبع مسار الحزم من جهازك للهدف[/dim]")
        console.print("  [bold cyan][4][/bold cyan] OS Fingerprint     — [dim]تخمين نظام التشغيل من قيمة TTL[/dim]")
        console.print("  [bold cyan][5][/bold cyan] DNS Lookup         — [dim]تحويل Domain لـ IP أو العكس[/dim]")
        console.print("  [bold cyan][6][/bold cyan] Wake-on-LAN        — [dim]إيقاظ جهاز عبر MAC Address[/dim]")
        console.print("  [bold cyan][0][/bold cyan] رجوع")

        choice = Prompt.ask("\n[cyan]اختيارك[/cyan]", choices=["0","1","2","3","4","5","6"])

        if choice == "0":
            break

        elif choice == "1":
            target = Prompt.ask("\n[cyan]أدخل نطاق الشبكة أو IP[/cyan] [dim](مثال: 192.168.1.0/24)[/dim]")
            try:
                network = ipaddress.ip_network(target, strict=False)
            except ValueError:
                try:
                    ip = socket.gethostbyname(target)
                    network = ipaddress.ip_network(ip + "/32", strict=False)
                except Exception:
                    console.print("[red][!] نطاق غير صالح[/red]"); continue
            hosts = list(network.hosts()) if network.num_addresses > 1 else [network.network_address]
            alive = []
            lock = threading.Lock()
            table = Table(title="[bold green]الأجهزة المكتشفة[/bold green]", box=box.DOUBLE_EDGE, border_style="green")
            table.add_column("IP", style="cyan", no_wrap=True)
            table.add_column("Hostname", style="white")
            table.add_column("Status", style="green")
            table.add_column("Ping (ms)", style="yellow")
            def ping_host(ip):
                start = time.time()
                for port in [80, 443, 22, 445]:
                    try:
                        s = socket.socket(); s.settimeout(0.4)
                        if s.connect_ex((str(ip), port)) == 0:
                            s.close()
                            return str(ip), (time.time()-start)*1000
                        s.close()
                    except: pass
                try:
                    r = subprocess.run(["ping","-c","1","-W","1",str(ip)], capture_output=True, timeout=2)
                    if r.returncode == 0:
                        return str(ip), (time.time()-start)*1000
                except: pass
                return None, 0
            console.print(f"\n[yellow][*] فحص {len(hosts)} جهاز...[/yellow]\n")
            with Progress(SpinnerColumn(style="red"), TextColumn("{task.description}"),
                          BarColumn(bar_width=40, style="red", complete_style="green"),
                          TextColumn("[green]{task.completed}/{task.total}"), TimeElapsedColumn(), console=console) as progress:
                task = progress.add_task("[cyan]فحص الشبكة...", total=len(hosts))
                with ThreadPoolExecutor(max_workers=100) as ex:
                    futures = {ex.submit(ping_host, ip): ip for ip in hosts}
                    for f in as_completed(futures):
                        ip_r, elapsed = f.result()
                        if ip_r:
                            try: hostname = socket.gethostbyaddr(ip_r)[0]
                            except: hostname = "N/A"
                            with lock:
                                alive.append(ip_r)
                                table.add_row(ip_r, hostname, "● مفتوح", f"{elapsed:.1f}")
                        progress.advance(task)
            console.print(f"\n[bold green][+] تم اكتشاف {len(alive)} جهاز[/bold green]\n")
            if alive: console.print(table)

        elif choice == "2":
            console.print("\n[yellow][*] جدول ARP — الأجهزة المتصلة مؤخراً:[/yellow]\n")
            try:
                r = subprocess.run(["arp","-a"], capture_output=True, text=True, timeout=5)
                if r.stdout.strip():
                    t = Table(title="ARP Table", box=box.SIMPLE, border_style="cyan")
                    t.add_column("Hostname", style="yellow"); t.add_column("IP", style="cyan"); t.add_column("MAC", style="green")
                    for line in r.stdout.strip().split("\n"):
                        parts = line.split()
                        if len(parts) >= 4:
                            t.add_row(parts[0], parts[1].strip("()"), parts[3])
                    console.print(t)
                else:
                    console.print("[yellow][!] جدول ARP فارغ[/yellow]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        elif choice == "3":
            host = Prompt.ask("[cyan]أدخل IP أو Domain[/cyan]")
            console.print(f"\n[yellow][*] Traceroute إلى {host}...[/yellow]\n")
            try:
                cmd = ["traceroute", "-n", "-w", "2", "-m", "20", host]
                r = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
                output = r.stdout or r.stderr
                t = Table(title=f"Traceroute → {host}", box=box.SIMPLE, border_style="cyan")
                t.add_column("Hop", style="yellow", width=4); t.add_column("IP", style="cyan"); t.add_column("RTT", style="green")
                for line in output.strip().split("\n")[1:]:
                    parts = line.split()
                    if parts and parts[0].isdigit():
                        hop = parts[0]
                        ip  = parts[1] if len(parts) > 1 else "*"
                        rtt = " ".join(parts[2:]) if len(parts) > 2 else "* * *"
                        t.add_row(hop, ip, rtt[:40])
                console.print(t)
            except FileNotFoundError:
                console.print("[red][!] ثبّت traceroute: apt install traceroute[/red]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        elif choice == "4":
            host = Prompt.ask("[cyan]أدخل IP أو Domain للتخمين[/cyan]")
            console.print(f"\n[yellow][*] OS Fingerprint على {host}...[/yellow]\n")
            try:
                ip = socket.gethostbyname(host)
                r = subprocess.run(["ping","-c","3","-W","2",ip], capture_output=True, text=True, timeout=10)
                ttl_val = None
                for line in r.stdout.split("\n"):
                    if "ttl=" in line.lower():
                        for part in line.split():
                            if "ttl=" in part.lower():
                                try: ttl_val = int(part.split("=")[1]); break
                                except: pass
                if ttl_val:
                    if ttl_val <= 64:   os_guess = "Linux / Unix / Android"
                    elif ttl_val <= 128: os_guess = "Windows"
                    elif ttl_val <= 255: os_guess = "Cisco / Network Device"
                    else:                os_guess = "Unknown"
                    t = Table(title="OS Fingerprint", box=box.SIMPLE, border_style="cyan")
                    t.add_column("Field", style="yellow"); t.add_column("Value", style="white")
                    t.add_row("IP", ip); t.add_row("TTL", str(ttl_val)); t.add_row("OS Guess", f"[bold green]{os_guess}[/bold green]")
                    console.print(t)
                else:
                    console.print("[yellow][-] لم يرد الجهاز على ping[/yellow]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        elif choice == "5":
            query = Prompt.ask("[cyan]أدخل Domain أو IP[/cyan]")
            console.print(f"\n[yellow][*] DNS Lookup: {query}[/yellow]\n")
            t = Table(title="DNS Lookup", box=box.SIMPLE, border_style="cyan")
            t.add_column("Type", style="yellow bold"); t.add_column("Result", style="white")
            try:
                ip = socket.gethostbyname(query)
                t.add_row("A (IPv4)", ip)
            except: t.add_row("A (IPv4)", "[red]فشل[/red]")
            try:
                names = socket.gethostbyaddr(query)
                t.add_row("Reverse DNS", names[0])
            except: pass
            try:
                import dns.resolver as dnsres
                for rtype in ["MX","NS","TXT","AAAA"]:
                    try:
                        ans = dnsres.resolve(query, rtype, lifetime=4)
                        for r2 in ans:
                            t.add_row(rtype, str(r2)[:80])
                    except: pass
            except: pass
            console.print(t)

        elif choice == "6":
            mac = Prompt.ask("[cyan]أدخل MAC Address[/cyan] [dim](مثال: AA:BB:CC:DD:EE:FF)[/dim]")
            iface = Prompt.ask("[cyan]واجهة الشبكة[/cyan]", default="eth0")
            console.print(f"\n[yellow][*] إرسال Magic Packet إلى {mac}...[/yellow]")
            try:
                mac_clean = mac.replace(":","").replace("-","")
                magic = bytes.fromhex("FF"*6 + mac_clean*16)
                with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                    s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
                    s.sendto(magic, ("<broadcast>", 9))
                console.print(f"[bold green][+] Magic Packet أُرسل! انتظر الجهاز يشتغل...[/bold green]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

    press_enter()


