def module_port_scanner():
    show_banner()
    console.print(Panel(
        "[bold blue][ 4 ] فحص المنافذ — Port Scanner[/bold blue]\n"
        "[dim]يكتشف المنافذ المفتوحة ويحدد الخدمات والبرامج المشغّلة عليها\n"
        "يدعم Quick / Full / Custom / Top100 مع جلب Banner من كل منفذ[/dim]",
        border_style="blue"
    ))

    while True:
        console.print("\n[blue]اختر العملية:[/blue]")
        console.print("  [bold blue][1][/bold blue] Quick Scan    — [dim]فحص المنافذ الشائعة (أسرع)[/dim]")
        console.print("  [bold blue][2][/bold blue] Full Scan     — [dim]فحص 1-10000 منفذ كامل[/dim]")
        console.print("  [bold blue][3][/bold blue] Custom Range  — [dim]تحديد نطاق مخصص من المنافذ[/dim]")
        console.print("  [bold blue][4][/bold blue] Service Probe — [dim]اكتشاف الخدمة وإصدارها بالتفصيل[/dim]")
        console.print("  [bold blue][5][/bold blue] UDP Ports     — [dim]فحص منافذ UDP الشائعة[/dim]")
        console.print("  [bold blue][6][/bold blue] Firewall Test — [dim]اختبار وجود جدار حماية/فلترة[/dim]")
        console.print("  [bold blue][0][/bold blue] رجوع")

        choice = Prompt.ask("\n[blue]اختيارك[/blue]", choices=["0","1","2","3","4","5","6"])
        if choice == "0": break

        if choice in ("1","2","3"):
            target = Prompt.ask("\n[blue]أدخل IP أو Domain[/blue]")
            try: ip = socket.gethostbyname(target)
            except: console.print(f"[red][!] تعذر حل {target}[/red]"); continue

            if choice == "1":   ports = list(COMMON_PORTS.keys())
            elif choice == "2": ports = list(range(1, 10001))
            else:
                rng = Prompt.ask("[blue]نطاق المنافذ[/blue]", default="1-1000")
                s_p, e_p = map(int, rng.split("-")); ports = list(range(s_p, e_p+1))

            open_ports = []; lock = threading.Lock()
            table = Table(title=f"[bold blue]المنافذ المفتوحة — {ip}[/bold blue]", box=box.DOUBLE_EDGE, border_style="blue")
            table.add_column("Port", style="cyan bold", justify="right", width=6)
            table.add_column("Service", style="green", width=14)
            table.add_column("Status", style="bold green", width=8)
            table.add_column("Banner / Info", style="dim white")

            def scan_port(port):
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM); s.settimeout(0.5)
                    if s.connect_ex((ip, port)) == 0:
                        banner = ""
                        try:
                            if port in (80, 8080, 8000, 8008, 8081):
                                s.send(b"HEAD / HTTP/1.0\r\nHost: " + ip.encode() + b"\r\n\r\n")
                            elif port == 22:
                                s.send(b"")
                            banner = s.recv(256).decode("utf-8", errors="ignore").strip().split("\n")[0][:70]
                        except: pass
                        s.close()
                        svc = COMMON_PORTS.get(port, "Unknown")
                        with lock:
                            open_ports.append(port)
                            table.add_row(str(port), svc, "● OPEN", banner)
                    else: s.close()
                except: pass

            console.print(f"\n[yellow][*] فحص {len(ports):,} منفذ على {ip}...[/yellow]\n")
            with Progress(SpinnerColumn(style="blue"), TextColumn("{task.description}"),
                          BarColumn(bar_width=40, style="blue", complete_style="green"),
                          TextColumn("[cyan]{task.completed}/{task.total}"), TimeElapsedColumn(), console=console) as prog:
                task = prog.add_task("[blue]فحص المنافذ...", total=len(ports))
                with ThreadPoolExecutor(max_workers=500) as ex:
                    for f in as_completed({ex.submit(scan_port, p): p for p in ports}):
                        f.result(); prog.advance(task)
            console.print(f"\n[bold green][+] {len(open_ports)} منفذ مفتوح[/bold green]\n")
            if open_ports: console.print(table)

        elif choice == "4":
            target = Prompt.ask("\n[blue]أدخل IP أو Domain[/blue]")
            try: ip = socket.gethostbyname(target)
            except: console.print(f"[red][!] فشل[/red]"); continue
            port_list = Prompt.ask("[blue]المنافذ المراد فحصها[/blue]", default="22,80,443,3306,5432,6379,8080,27017")
            ports = [int(p.strip()) for p in port_list.split(",")]
            table = Table(title=f"Service Probe — {ip}", box=box.DOUBLE_EDGE, border_style="blue")
            table.add_column("Port", style="cyan bold"); table.add_column("Service", style="green")
            table.add_column("Status", style="white"); table.add_column("Full Banner", style="dim")
            for port in ports:
                status = "CLOSED"; banner = ""; svc = COMMON_PORTS.get(port, "Unknown")
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM); s.settimeout(2)
                    if s.connect_ex((ip, port)) == 0:
                        status = "[bold green]OPEN[/bold green]"
                        try:
                            s.send(b"HEAD / HTTP/1.0\r\n\r\n") if port in (80,8080,443) else s.send(b"\n")
                            banner = s.recv(512).decode("utf-8", errors="ignore").strip()[:120]
                        except: pass
                    s.close()
                except: pass
                table.add_row(str(port), svc, status, banner)
            console.print(table)

        elif choice == "5":
            target = Prompt.ask("\n[blue]أدخل IP الهدف[/blue]")
            udp_ports = {53:"DNS",67:"DHCP",68:"DHCP",69:"TFTP",123:"NTP",137:"NetBIOS",
                         161:"SNMP",162:"SNMP-Trap",500:"IPSec",514:"Syslog",520:"RIP",
                         1194:"OpenVPN",1900:"UPnP",4500:"IPSec-NAT",5353:"mDNS"}
            console.print(f"\n[yellow][*] فحص {len(udp_ports)} UDP port على {target}...[/yellow]")
            console.print("[dim]ملاحظة: UDP الفحص غير موثوق بدون root — نعتمد على ICMP unreachable[/dim]\n")
            table = Table(title=f"UDP Ports — {target}", box=box.SIMPLE, border_style="blue")
            table.add_column("Port/UDP", style="cyan"); table.add_column("Service", style="green")
            table.add_column("Status", style="yellow")
            for port, svc in udp_ports.items():
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(1)
                    s.sendto(b"\x00"*8, (target, port))
                    try: s.recv(128); state = "[green]open/responding[/green]"
                    except socket.timeout: state = "[yellow]open|filtered[/yellow]"
                    s.close()
                except: state = "[dim]filtered[/dim]"
                table.add_row(str(port), svc, state)
            console.print(table)

        elif choice == "6":
            target = Prompt.ask("\n[blue]أدخل IP أو Domain[/blue]")
            try: ip = socket.gethostbyname(target)
            except: console.print("[red][!] فشل[/red]"); continue
            console.print(f"\n[yellow][*] اختبار جدار الحماية على {ip}...[/yellow]\n")
            tests = []
            for port in [80, 443, 22, 21, 23, 3389, 8080]:
                start = time.time()
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM); s.settimeout(2)
                    result = s.connect_ex((ip, port)); elapsed = (time.time()-start)*1000; s.close()
                    if result == 0:       state = "[green]OPEN[/green]";    note = "مفتوح — لا يوجد فلترة"
                    elif elapsed > 1900:  state = "[yellow]FILTERED[/yellow]"; note = "جدار حماية يُسقط الحزم (Drop)"
                    else:                 state = "[red]CLOSED[/red]";     note = "مغلق — جدار حماية أو خدمة متوقفة"
                except: state, note, elapsed = "[dim]ERROR[/dim]", "خطأ", 0
                tests.append((str(port), COMMON_PORTS.get(port,"?"), state, note, f"{elapsed:.0f}ms"))
            table = Table(title=f"Firewall Test — {ip}", box=box.DOUBLE_EDGE, border_style="blue")
            table.add_column("Port", style="cyan"); table.add_column("Service", style="green")
            table.add_column("Status", style="white"); table.add_column("ملاحظة", style="yellow")
            table.add_column("RTT", style="dim")
            for row in tests: table.add_row(*row)
            console.print(table)
            if all("FILTERED" in r[2] for r in tests):
                console.print("[bold yellow][!] يبدو أن جدار حماية Drop يحجب معظم المنافذ[/bold yellow]")

    press_enter()


