def module_subdomain_finder():
    show_banner()
    console.print(Panel(
        "[bold yellow][ 5 ] اكتشاف Sub-domains[/bold yellow]\n"
        "[dim]يبحث عن النطاقات الفرعية لموقعك المستهدف بعدة طرق\n"
        "DNS Brute Force / Certificate Transparency / Zone Transfer / Reverse DNS[/dim]",
        border_style="yellow"
    ))

    while True:
        console.print("\n[yellow]اختر طريقة الاكتشاف:[/yellow]")
        console.print("  [bold yellow][1][/bold yellow] DNS Brute Force        — [dim]يجرب قائمة أسماء شائعة ويفحص وجودها[/dim]")
        console.print("  [bold yellow][2][/bold yellow] Certificate Transparency— [dim]يبحث في سجلات SSL/TLS العامة (crt.sh)[/dim]")
        console.print("  [bold yellow][3][/bold yellow] DNS Zone Transfer      — [dim]يحاول استخراج كل records من DNS Server[/dim]")
        console.print("  [bold yellow][4][/bold yellow] Reverse DNS Range      — [dim]يبحث في نطاق IP عن Hostnames[/dim]")
        console.print("  [bold yellow][5][/bold yellow] All Methods            — [dim]يجمع كل الطرق السابقة معاً[/dim]")
        console.print("  [bold yellow][0][/bold yellow] رجوع")

        choice = Prompt.ask("\n[yellow]اختيارك[/yellow]", choices=["0","1","2","3","4","5"])
        if choice == "0": break

        domain_raw = Prompt.ask("[yellow]أدخل النطاق الرئيسي[/yellow] [dim](مثال: example.com)[/dim]")
        domain = domain_raw.replace("http://","").replace("https://","").strip("/").split("/")[0]

        if choice in ("1","5"):
            console.print(f"\n[yellow][*] DNS Brute Force — فحص {len(SUBDOMAINS)} اسم على {domain}...[/yellow]\n")
            found = []; lock = threading.Lock()
            table = Table(title=f"Sub-domains (DNS) — {domain}", box=box.DOUBLE_EDGE, border_style="yellow")
            table.add_column("Subdomain", style="cyan"); table.add_column("IP", style="green")
            table.add_column("HTTP", style="yellow"); table.add_column("HTTPS", style="blue")

            def check_sub(sub):
                full = f"{sub}.{domain}"
                try:
                    ip = socket.gethostbyname(full)
                    h_code = s_code = "N/A"
                    try:
                        r = requests.get(f"http://{full}", timeout=3, headers={"User-Agent":get_random_ua()}, allow_redirects=True, verify=False)
                        h_code = str(r.status_code)
                    except: pass
                    try:
                        r = requests.get(f"https://{full}", timeout=3, headers={"User-Agent":get_random_ua()}, allow_redirects=True, verify=False)
                        s_code = str(r.status_code)
                    except: pass
                    with lock:
                        found.append(full)
                        table.add_row(full, ip, h_code, s_code)
                except: pass

            with Progress(SpinnerColumn(style="yellow"), TextColumn("{task.description}"),
                          BarColumn(bar_width=40, style="yellow", complete_style="green"),
                          TextColumn("{task.completed}/{task.total}"), TimeElapsedColumn(), console=console) as prog:
                task = prog.add_task("[yellow]DNS Brute Force...", total=len(SUBDOMAINS))
                with ThreadPoolExecutor(max_workers=50) as ex:
                    for f in as_completed({ex.submit(check_sub, s): s for s in SUBDOMAINS}):
                        f.result(); prog.advance(task)
            console.print(f"\n[bold green][+] DNS: {len(found)} sub-domain[/bold green]")
            if found: console.print(table)

        if choice in ("2","5"):
            console.print(f"\n[yellow][*] Certificate Transparency — crt.sh لـ {domain}...[/yellow]\n")
            try:
                r = requests.get(f"https://crt.sh/?q=%.{domain}&output=json", timeout=15,
                                  headers={"User-Agent": get_random_ua()})
                if r.status_code == 200:
                    entries = r.json()
                    crt_subs = set()
                    for e in entries:
                        for name in e.get("name_value","").split("\n"):
                            n = name.strip().lstrip("*.")
                            if n.endswith(domain) and n != domain:
                                crt_subs.add(n)
                    if crt_subs:
                        t = Table(title=f"Certificate Transparency — {domain}", box=box.SIMPLE, border_style="yellow")
                        t.add_column("#", style="dim", width=4); t.add_column("Subdomain", style="cyan")
                        for i, sub in enumerate(sorted(crt_subs), 1):
                            t.add_row(str(i), sub)
                        console.print(t)
                        console.print(f"[bold green][+] crt.sh: {len(crt_subs)} sub-domain[/bold green]")
                    else:
                        console.print("[yellow][-] لا توجد نتائج في crt.sh[/yellow]")
                else:
                    console.print(f"[red][!] crt.sh أعاد {r.status_code}[/red]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        if choice in ("3","5"):
            console.print(f"\n[yellow][*] DNS Zone Transfer على {domain}...[/yellow]\n")
            try:
                ns_records = []
                try:
                    import dns.resolver as dnsres
                    ans = dnsres.resolve(domain, "NS", lifetime=5)
                    ns_records = [str(r) for r in ans]
                except: ns_records = []
                if not ns_records:
                    console.print("[yellow][-] لم يتم الحصول على NS records[/yellow]")
                else:
                    import dns.zone, dns.query
                    for ns in ns_records:
                        ns_ip = socket.gethostbyname(ns.rstrip("."))
                        try:
                            z = dns.zone.from_xfr(dns.query.xfr(ns_ip, domain, timeout=10))
                            names = [str(n) for n in z.nodes.keys()]
                            console.print(f"[bold green][+] Zone Transfer نجح من {ns}![/bold green]")
                            t = Table(title=f"Zone Transfer — {domain}", box=box.SIMPLE, border_style="yellow")
                            t.add_column("Name", style="cyan"); t.add_column("TTL", style="dim"); t.add_column("Record", style="white")
                            for name in sorted(names)[:50]:
                                node = z.nodes[dns.name.from_text(name)]
                                t.add_row(f"{name}.{domain}", "—", str(node.to_text(name, None, None, None))[:80])
                            console.print(t)
                        except Exception:
                            console.print(f"[dim][-] Zone Transfer مرفوض من {ns}[/dim]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        if choice in ("4","5"):
            ip_range = Prompt.ask("[yellow]أدخل نطاق IP[/yellow]", default="192.168.1")
            count = int(Prompt.ask("[yellow]عدد الـ IPs[/yellow]", default="50"))
            console.print(f"\n[yellow][*] Reverse DNS: {ip_range}.1 — {ip_range}.{count}...[/yellow]\n")
            t = Table(title=f"Reverse DNS — {ip_range}.x", box=box.SIMPLE, border_style="yellow")
            t.add_column("IP", style="cyan"); t.add_column("Hostname", style="green")
            found_rev = 0
            for i in range(1, count+1):
                ip = f"{ip_range}.{i}"
                try:
                    name = socket.gethostbyaddr(ip)[0]
                    t.add_row(ip, name); found_rev += 1
                except: pass
            console.print(f"[bold green][+] {found_rev} hostname[/bold green]")
            if found_rev: console.print(t)

    press_enter()


