def module_info_gathering():
    show_banner()
    console.print(Panel(
        "[bold green][ 6 ] جمع المعلومات — Information Gathering[/bold green]\n"
        "[dim]يجمع معلومات شاملة عن الهدف: WHOIS / DNS / Headers / SSL / WAF / Technologies\n"
        "يُستخدم في مرحلة Reconnaissance قبل الاختبار[/dim]",
        border_style="green"
    ))

    while True:
        console.print("\n[green]اختر العملية:[/green]")
        console.print("  [bold green][1][/bold green] Full Recon         — [dim]جمع كل المعلومات المتاحة دفعة واحدة[/dim]")
        console.print("  [bold green][2][/bold green] WHOIS Lookup       — [dim]معلومات تسجيل النطاق والمالك[/dim]")
        console.print("  [bold green][3][/bold green] DNS Records        — [dim]كل records: A / MX / NS / TXT / AAAA[/dim]")
        console.print("  [bold green][4][/bold green] HTTP Headers       — [dim]headers الخادم وما يكشفه عن التقنية[/dim]")
        console.print("  [bold green][5][/bold green] SSL/TLS Inspector  — [dim]تفاصيل شهادة الأمان وصلاحيتها[/dim]")
        console.print("  [bold green][6][/bold green] WAF Detector       — [dim]اكتشاف جدار حماية تطبيقات الويب[/dim]")
        console.print("  [bold green][7][/bold green] Technology Stack   — [dim]اكتشاف التقنيات المستخدمة في الموقع[/dim]")
        console.print("  [bold green][8][/bold green] Email Harvester    — [dim]البحث عن emails مرتبطة بالنطاق[/dim]")
        console.print("  [bold green][0][/bold green] رجوع")

        choice = Prompt.ask("\n[green]اختيارك[/green]", choices=["0","1","2","3","4","5","6","7","8"])
        if choice == "0": break

        target = Prompt.ask("\n[green]أدخل Domain أو IP[/green]")
        target_clean = target.replace("http://","").replace("https://","").strip("/").split("/")[0]

        def do_whois():
            console.print(Panel("[bold]WHOIS[/bold]", border_style="green"))
            try:
                w = whois.whois(target_clean)
                t = Table(box=box.SIMPLE, border_style="green")
                t.add_column("Field", style="green bold", width=20); t.add_column("Value", style="white")
                fields = [("Domain Name","domain_name"),("Registrar","registrar"),
                          ("Creation Date","creation_date"),("Expiry Date","expiration_date"),
                          ("Name Servers","name_servers"),("Status","status"),
                          ("Registrant Org","org"),("Country","country")]
                for label, key in fields:
                    val = getattr(w, key, None)
                    if val:
                        if isinstance(val, list): val = ", ".join(str(v) for v in val[:3])
                        t.add_row(label, str(val)[:100])
                console.print(t)
            except Exception as e:
                console.print(f"[red][!] WHOIS: {e}[/red]")

        def do_dns():
            console.print(Panel("[bold]DNS Records[/bold]", border_style="cyan"))
            import dns.resolver as dnsres
            t = Table(box=box.SIMPLE, border_style="cyan")
            t.add_column("Type", style="cyan bold", width=8); t.add_column("Value", style="white")
            for rtype in ["A","AAAA","MX","NS","TXT","SOA","CAA","CNAME","PTR"]:
                try:
                    ans = dnsres.resolve(target_clean, rtype, lifetime=4)
                    for r in ans:
                        t.add_row(rtype, str(r)[:100])
                except: pass
            console.print(t)

        def do_headers():
            console.print(Panel("[bold]HTTP Headers[/bold]", border_style="yellow"))
            security_headers = {"strict-transport-security":"✓ HSTS","content-security-policy":"✓ CSP",
                                "x-frame-options":"✓ Clickjacking Protection","x-xss-protection":"✓ XSS Filter",
                                "x-content-type-options":"✓ MIME Sniff","referrer-policy":"✓ Referrer Policy",
                                "permissions-policy":"✓ Permissions","x-powered-by":"⚠ Exposed Tech",
                                "server":"⚠ Server Info","x-aspnet-version":"⚠ ASP.NET Version"}
            risky = {"x-powered-by","server","x-aspnet-version","x-debug-token","x-env","x-backend-server"}
            for scheme in ("https","http"):
                try:
                    r = requests.get(f"{scheme}://{target_clean}", timeout=8,
                                     headers={"User-Agent": get_random_ua()}, verify=False)
                    t = Table(title=f"Headers [{scheme.upper()}] — {r.status_code}", box=box.SIMPLE, border_style="yellow")
                    t.add_column("Header", style="yellow", width=30); t.add_column("Value", style="white")
                    t.add_column("Security", style="green")
                    for k, v in r.headers.items():
                        sec = security_headers.get(k.lower(), "")
                        color = "red" if k.lower() in risky else "green"
                        t.add_row(k, v[:80], f"[{color}]{sec}[/{color}]" if sec else "")
                    console.print(t)
                    missing = [h for h in ["strict-transport-security","content-security-policy",
                                           "x-frame-options","x-content-type-options"] if h not in {k.lower() for k in r.headers}]
                    if missing:
                        console.print(f"[red][!] مفقود: {', '.join(missing)}[/red]")
                    break
                except: pass

        def do_ssl():
            console.print(Panel("[bold]SSL/TLS Certificate[/bold]", border_style="blue"))
            import ssl, datetime as dt_mod
            try:
                ctx = ssl.create_default_context()
                with ctx.wrap_socket(socket.socket(), server_hostname=target_clean) as s:
                    s.settimeout(5); s.connect((target_clean, 443))
                    cert = s.getpeercert()
                t = Table(box=box.SIMPLE, border_style="blue")
                t.add_column("Field", style="blue bold", width=20); t.add_column("Value", style="white")
                subj = dict(x[0] for x in cert.get("subject",[]))
                issuer = dict(x[0] for x in cert.get("issuer",[]))
                t.add_row("Subject CN", subj.get("commonName","N/A"))
                t.add_row("Issuer", issuer.get("organizationName","N/A"))
                t.add_row("Valid From", cert.get("notBefore","N/A"))
                t.add_row("Valid Until", cert.get("notAfter","N/A"))
                t.add_row("Protocol", s.version() if hasattr(s,"version") else "N/A")
                sans = [v for t2, v in cert.get("subjectAltName",[]) if t2 == "DNS"]
                if sans: t.add_row("SANs", ", ".join(sans[:10]))
                console.print(t)
            except Exception as e:
                console.print(f"[red][!] SSL: {e}[/red]")

        def do_waf():
            console.print(Panel("[bold]WAF Detection[/bold]", border_style="red"))
            waf_signatures = {
                "Cloudflare": ["cloudflare","cf-ray","__cfduid","cf-cache-status"],
                "AWS WAF":    ["awselb","x-amzn-requestid","x-amz-cf-id"],
                "Akamai":     ["akamai","x-check-cacheable","x-cache-key"],
                "Imperva":    ["incap_ses","visid_incap","incapsula"],
                "F5 BIG-IP":  ["ts01","bigipserver","x-wa-info"],
                "Sucuri":     ["sucuri","x-sucuri-id","x-sucuri-cache"],
                "ModSecurity":["mod_security","modsec","x-modsecurity"],
                "Wordfence":  ["wordfence"],
                "Barracuda":  ["barra_counter_session","bnsession"],
            }
            try:
                r = requests.get(f"http://{target_clean}", timeout=8, headers={"User-Agent": get_random_ua()}, verify=False)
                headers_str = str(r.headers).lower() + r.text[:500].lower()
                cookies_str = str(r.cookies).lower()
                detected = []
                for waf, sigs in waf_signatures.items():
                    if any(s in headers_str or s in cookies_str for s in sigs):
                        detected.append(waf)
                if detected:
                    for waf in detected:
                        console.print(f"[bold red][+] WAF مكتشف: {waf}[/bold red]")
                else:
                    console.print("[green][-] لا يوجد WAF واضح مكتشف[/green]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        def do_tech():
            console.print(Panel("[bold]Technology Stack[/bold]", border_style="magenta"))
            tech_patterns = {
                "WordPress":    ["wp-content","wp-includes","wordpress"],
                "Joomla":       ["joomla","com_content","Joomla!"],
                "Drupal":       ["drupal","sites/default","Drupal"],
                "Laravel":      ["laravel_session","illuminate","Laravel"],
                "Django":       ["csrfmiddlewaretoken","django","__admin"],
                "React":        ["react","__REACT","_reactFiber","createElement"],
                "Vue.js":       ["vue","__vue__","v-if","v-bind"],
                "Angular":      ["ng-app","angular","ng-controller","_angular"],
                "jQuery":       ["jquery","jQuery"],
                "Bootstrap":    ["bootstrap.css","bootstrap.min.js"],
                "PHP":          ["php","x-powered-by: php",".php"],
                "ASP.NET":      ["asp.net","viewstate","__dopostback","aspx"],
                "Node.js":      ["express","nodejs","node.js"],
                "Nginx":        ["nginx"],
                "Apache":       ["apache","apache/"],
                "CloudFlare":   ["cloudflare","cf-ray"],
            }
            try:
                r = requests.get(f"http://{target_clean}", timeout=8, headers={"User-Agent": get_random_ua()}, verify=False)
                content = r.text.lower() + str(r.headers).lower()
                t = Table(title=f"Technologies — {target_clean}", box=box.SIMPLE, border_style="magenta")
                t.add_column("Technology", style="magenta bold"); t.add_column("Evidence", style="dim")
                found_tech = False
                for tech, patterns in tech_patterns.items():
                    matches = [p for p in patterns if p.lower() in content]
                    if matches:
                        t.add_row(tech, ", ".join(matches[:3]))
                        found_tech = True
                console.print(t if found_tech else "[yellow][-] لا يمكن تحديد التقنيات[/yellow]")
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        def do_email():
            console.print(Panel("[bold]Email Harvesting[/bold]", border_style="yellow"))
            try:
                import dns.resolver as dnsres
                emails = []
                # MX records
                try:
                    ans = dnsres.resolve(target_clean, "MX", lifetime=5)
                    for r in ans:
                        console.print(f"[green]MX Server: {r.exchange}[/green]")
                except: pass
                # TXT SPF
                try:
                    ans = dnsres.resolve(target_clean, "TXT", lifetime=5)
                    for r in ans:
                        txt = str(r)
                        if "v=spf" in txt.lower() or "include:" in txt:
                            console.print(f"[cyan]SPF Record: {txt[:120]}[/cyan]")
                except: pass
                # Common email patterns
                patterns = [f"admin@{target_clean}", f"info@{target_clean}",
                            f"webmaster@{target_clean}", f"support@{target_clean}",
                            f"contact@{target_clean}", f"abuse@{target_clean}",
                            f"security@{target_clean}", f"noc@{target_clean}"]
                t = Table(title="Common Emails", box=box.SIMPLE, border_style="yellow")
                t.add_column("Email", style="cyan"); t.add_column("ملاحظة", style="dim")
                for em in patterns:
                    t.add_row(em, "محتمل — تحقق يدوياً")
                console.print(t)
            except Exception as e:
                console.print(f"[red][!] {e}[/red]")

        if choice == "1":
            for fn in [do_whois, do_dns, do_headers, do_ssl, do_waf, do_tech]:
                fn(); console.print()
        elif choice == "2": do_whois()
        elif choice == "3": do_dns()
        elif choice == "4": do_headers()
        elif choice == "5": do_ssl()
        elif choice == "6": do_waf()
        elif choice == "7": do_tech()
        elif choice == "8": do_email()

    press_enter()


