def module_wireless():
    show_banner()
    console.print(Panel(
        "[bold bright_cyan][ 9 ] Wireless Testing — فحص الشبكات اللاسلكية[/bold bright_cyan]\n"
        "[dim]أدوات فحص واختبار شبكات WiFi\n"
        "Scanner / ARP / Passive Capture / WPS / Deauth / Handshake / Crack Guide[/dim]",
        border_style="bright_cyan"
    ))

    while True:
        console.print("\n[bright_cyan]اختر العملية:[/bright_cyan]")
