def _get_ua():
    return "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124.0 Safari/537.36"


def _save_results_to_file(filename: str, lines: list):
    path = os.path.join(os.getcwd(), filename)
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    console.print(f"\n[bold green][+] النتائج حُفظت في:[/bold green] [cyan]{path}[/cyan]")


# ── USERNAME ────────────────────────────────────────────────────

def osint_username(username: str):
    console.print(f"\n[pink1][*] فحص اليوزرنيم: [bold]{username}[/bold] على {len(SOCIAL_PLATFORMS)} منصة...[/pink1]\n")
    found = []
    not_found = []
    headers = {"User-Agent": _get_ua()}

    with Progress(SpinnerColumn(), TextColumn("[progress.description]{task.description}"),
                  BarColumn(), TextColumn("{task.completed}/{task.total}"),
                  console=console, transient=True) as progress:
        task = progress.add_task("[pink1]فحص المنصات...", total=len(SOCIAL_PLATFORMS))

        def check_platform(name, url_tmpl):
            url = url_tmpl.format(username)
            try:
                r = requests.get(url, headers=headers, timeout=9, allow_redirects=True)
                ok = (r.status_code == 200)
                return (name, url, ok)
            except Exception:
                return (name, url, False)

        with ThreadPoolExecutor(max_workers=15) as ex:
            futures = {ex.submit(check_platform, n, u): n for n, u in SOCIAL_PLATFORMS}
            for fut in as_completed(futures):
                name, url, ok = fut.result()
                (found if ok else not_found).append((name, url))
                progress.advance(task)

    # Print results
    console.print(f"\n[bold pink1]═══ نتائج Username: {username} ═══[/bold pink1]\n")
    
    found_table = Table(box=box.SIMPLE_HEAVY, border_style="green", show_header=True)
    found_table.add_column("المنصة",  style="bold white",  width=18)
    found_table.add_column("الرابط",  style="cyan")
    for name, url in sorted(found, key=lambda x: x[0]):
        found_table.add_row(f"[green]✓[/green] {name}", url)
    
    console.print(found_table)
    console.print(f"[bold green][+] موجود في: {len(found)} منصة[/bold green]  |  "
                  f"[dim red]غير موجود: {len(not_found)} منصة[/dim red]")

    # Save option
    save = Prompt.ask("\n[pink1]هل تريد حفظ النتائج في ملف؟ (y/n)[/pink1]", default="n")
    if save.lower() == "y":
        lines = [f"VALLAINS OSINT — Username: {username}", "=" * 50, ""]
        lines.append(f"[موجود في {len(found)} منصة]")
        for name, url in found:
            lines.append(f"[+] {name}: {url}")
        lines.append("")
        lines.append(f"[غير موجود في {len(not_found)} منصة]")
        for name, url in not_found:
            lines.append(f"[-] {name}: {url}")
        _save_results_to_file(f"osint_username_{username}.txt", lines)


# ── PHONE ────────────────────────────────────────────────────────

def osint_phone(phone: str):
    console.print(f"\n[pink1][*] تحليل رقم الهاتف: [bold]{phone}[/bold][/pink1]\n")
    clean = "".join(c for c in phone if c.isdigit() or c == "+")
    if not clean.startswith("+"):
        clean = "+" + clean

    # Country detection (longest prefix first)
    country_ar = country_en = code_str = "غير معروف"
    prefix_matched = ""
    for prefix, (ar, en, cc) in sorted(COUNTRY_CODES.items(), key=lambda x: -len(x[0])):
        if clean.startswith(prefix):
            country_ar, country_en, code_str = ar, en, cc
            prefix_matched = prefix
            break

    local_number = clean[len(prefix_matched):]
    digits_only  = clean.replace("+", "")

    # Format variants
    intl_spaces  = clean[:len(prefix_matched)] + " " + " ".join(
        local_number[i:i+3] for i in range(0, len(local_number), 3)
    )
    intl_dashes  = clean[:len(prefix_matched)] + "-" + "-".join(
        local_number[i:i+3] for i in range(0, len(local_number), 3)
    )

    # Validity
    num_len = len(clean.replace("+", ""))
    if num_len < 7:
        validity = "[red]غير صالح (قصير جداً)[/red]"
    elif num_len > 15:
        validity = "[red]غير صالح (طويل جداً)[/red]"
    elif 10 <= num_len <= 13:
        validity = "[bold green]صالح محتمل ✓[/bold green]"
    else:
        validity = "[yellow]مقبول[/yellow]"

    table = Table(box=box.ROUNDED, border_style="pink1", title="[bold pink1]Phone OSINT[/bold pink1]")
    table.add_column("المعلومة",  style="bold pink1", width=22)
    table.add_column("القيمة",    style="white")
    table.add_row("الرقم الأصلي",      phone)
    table.add_row("الرقم المنظّف",     clean)
    table.add_row("الأرقام فقط",       digits_only)
    table.add_row("تنسيق دولي (مسافة)",intl_spaces)
    table.add_row("تنسيق دولي (شرطة)", intl_dashes)
    table.add_row("الدولة (عربي)",     country_ar)
    table.add_row("الدولة (إنجليزي)", country_en)
    table.add_row("كود الدولة ISO",    code_str)
    table.add_row("كود الاتصال",       prefix_matched)
