# ── EMAIL ────────────────────────────────────────────────────────

def osint_email(email: str):
    console.print(f"\n[pink1][*] تحليل البريد الإلكتروني: [bold]{email}[/bold][/pink1]\n")

    if "@" not in email:
        console.print("[red][!] بريد غير صالح[/red]")
        return

    local_part, domain = email.rsplit("@", 1)
    is_gmail = domain.lower() in ("gmail.com", "googlemail.com")
    is_yahoo = domain.lower() in ("yahoo.com", "yahoo.co.uk", "ymail.com")
    is_outlook = domain.lower() in ("outlook.com", "hotmail.com", "live.com", "msn.com")

    provider = "Gmail" if is_gmail else ("Yahoo" if is_yahoo else ("Outlook/MS" if is_outlook else domain))

    table = Table(box=box.ROUNDED, border_style="pink1", title="[bold pink1]Email OSINT[/bold pink1]")
    table.add_column("المعلومة",  style="bold pink1", width=22)
    table.add_column("القيمة",    style="white")
    table.add_row("البريد الكامل",   email)
    table.add_row("المستخدم",        local_part)
    table.add_row("النطاق",          domain)
    table.add_row("المزوّد",          provider)
    table.add_row("Gmail؟",          "[green]نعم ✓[/green]" if is_gmail else "[dim]لا[/dim]")
    console.print(table)

    # DNS MX
    console.print("\n[yellow][*] فحص DNS MX...[/yellow]")
    try:
        answers = dns.resolver.resolve(domain, "MX")
        console.print(f"[green][+] سجلات MX: {len(answers)} — النطاق يستقبل بريداً[/green]")
        for r in answers:
            console.print(f"  [cyan]→[/cyan] {str(r.exchange).rstrip('.')} (priority {r.preference})")
    except Exception as e:
        console.print(f"[yellow][-] لا توجد MX: {e}[/yellow]")

    # DNS A/AAAA
    try:
        a_rec = dns.resolver.resolve(domain, "A")
        console.print(f"[green][+] IP النطاق: {[str(r) for r in a_rec]}[/green]")
    except Exception:
        pass

    # Gravatar
    console.print("\n[yellow][*] فحص Gravatar...[/yellow]")
    try:
        import hashlib as _hl
        h = _hl.md5(email.strip().lower().encode()).hexdigest()
        r = requests.get(f"https://www.gravatar.com/avatar/{h}?d=404", timeout=6)
        if r.status_code == 200:
            console.print(f"[bold green][+] Gravatar موجود! [/bold green][cyan]https://gravatar.com/{h}[/cyan]")
        else:
            console.print("[dim][-] لا يوجد Gravatar[/dim]")
    except Exception:
        pass

    # Social username guess from local_part
    console.print(f"\n[yellow][*] بحث بـ '{local_part}' على منصات شهيرة...[/yellow]")
    quick_checks = [
        ("GitHub",    f"https://github.com/{local_part}"),
        ("Twitter/X", f"https://twitter.com/{local_part}"),
        ("Reddit",    f"https://www.reddit.com/user/{local_part}"),
        ("TikTok",    f"https://www.tiktok.com/@{local_part}"),
        ("Instagram", f"https://www.instagram.com/{local_part}/"),
    ]
    hdr = {"User-Agent": _get_ua()}
    for name, url in quick_checks:
        try:
            r = requests.get(url, headers=hdr, timeout=7)
            st = "[bold green]✓ محتمل[/bold green]" if r.status_code == 200 else "[dim red]✗[/dim red]"
            console.print(f"  {st} {name}: [cyan]{url}[/cyan]")
        except Exception:
            console.print(f"  [dim]? {name}: timeout[/dim]")

    # Provider-specific
    if is_gmail:
        console.print("\n[bold green][Gmail-specific][/bold green]")
        console.print(f"  Google Account: https://accounts.google.com/")
        console.print(f"  YouTube:  https://www.youtube.com/@{local_part}")
        console.print(f"  Google Photos: https://photos.google.com/u/0/")
    if is_outlook:
        console.print("\n[bold cyan][Microsoft Account][/bold cyan]")
        console.print(f"  https://account.microsoft.com/")
        console.print(f"  Xbox Gamertag guess: https://www.xbox.com/en-US/play/user/{local_part}")

    # HaveIBeenPwned
    console.print(f"\n[yellow][*] فحص التسريبات...[/yellow]")
    try:
        r = requests.get(
            f"https://haveibeenpwned.com/api/v3/breachedaccount/{email}",
            headers={"hibp-api-key": "free", "User-Agent": "VALLAINS-OSINT"},
            timeout=7
        )
        if r.status_code == 200:
            breaches = r.json()
            console.print(f"[bold red][!] تسريبات: {len(breaches)} خرق مسجّل![/bold red]")
            for b in breaches[:10]:
                console.print(f"  [red]→[/red] {b.get('Name','?')} ({b.get('BreachDate','?')})")
        elif r.status_code == 404:
            console.print("[green][+] لم يُعثر على تسريبات في HIBP[/green]")
        else:
            console.print(f"[dim][-] HIBP: {r.status_code} (يحتاج API key للتحقق الكامل)[/dim]")
    except Exception:
        pass

    console.print(f"\n  [cyan]→[/cyan] https://haveibeenpwned.com/account/{email}")
    console.print(f"  [cyan]→[/cyan] https://breachdirectory.org/")
    console.print(f"  [cyan]→[/cyan] https://intelx.io/?s={email}")

    # Save
    save = Prompt.ask("\n[pink1]حفظ النتائج؟ (y/n)[/pink1]", default="n")
    if save.lower() == "y":
        lines = [
            f"VALLAINS OSINT — Email: {email}", "=" * 50, "",
            f"المستخدم:  {local_part}",
            f"النطاق:    {domain}",
            f"المزوّد:    {provider}",
            "",
            f"HIBP:      https://haveibeenpwned.com/account/{email}",
            f"IntelX:    https://intelx.io/?s={email}",
            f"Gravatar:  https://en.gravatar.com/{local_part}",
        ]
        _save_results_to_file(f"osint_email_{local_part}.txt", lines)


# ── IP OSINT ──────────────────────────────────────────────────────

def osint_ip(ip_addr: str):
    console.print(f"\n[pink1][*] تحليل عنوان IP: [bold]{ip_addr}[/bold][/pink1]\n")

    results = {}

    # ip-api.com (free, no key needed)
    console.print("[yellow][*] جاري الاستعلام...[/yellow]")
    try:
        r = requests.get(
            f"http://ip-api.com/json/{ip_addr}?fields=status,message,country,countryCode,"
            f"regionName,city,zip,lat,lon,timezone,isp,org,as,query,mobile,proxy,hosting",
            timeout=8
        )
        if r.status_code == 200:
            d = r.json()
            if d.get("status") == "success":
                results = d
    except Exception as e:
        console.print(f"[red][!] {e}[/red]")

    if results:
        table = Table(box=box.ROUNDED, border_style="pink1", title="[bold pink1]IP OSINT[/bold pink1]")
        table.add_column("المعلومة",  style="bold pink1", width=22)
        table.add_column("القيمة",    style="white")
        table.add_row("IP",            results.get("query", ip_addr))
        table.add_row("الدولة",        f"{results.get('country','')} ({results.get('countryCode','')})")
        table.add_row("المنطقة",       results.get("regionName", ""))
        table.add_row("المدينة",       results.get("city", ""))
        table.add_row("الرمز البريدي", results.get("zip", ""))
        table.add_row("الموقع",        f"{results.get('lat','')} , {results.get('lon','')} ")
        table.add_row("المنطقة الزمنية",results.get("timezone", ""))
        table.add_row("مزوّد الخدمة",  results.get("isp", ""))
        table.add_row("المنظمة",       results.get("org", ""))
        table.add_row("AS",            results.get("as", ""))
        table.add_row("موبايل؟",       "[yellow]نعم[/yellow]" if results.get("mobile") else "لا")
        table.add_row("Proxy/VPN؟",    "[red]نعم ⚠[/red]"   if results.get("proxy") else "[green]لا[/green]")
        table.add_row("Hosting؟",      "[yellow]نعم[/yellow]" if results.get("hosting") else "لا")
        console.print(table)

        lat, lon = results.get("lat",""), results.get("lon","")
        if lat and lon:
            console.print(f"\n[cyan]→ Google Maps:[/cyan] https://maps.google.com/?q={lat},{lon}")

    # Additional services
    console.print(f"\n[bold yellow][+] روابط تحليل إضافية:[/bold yellow]")
    console.print(f"  [cyan]→[/cyan] https://www.shodan.io/host/{ip_addr}")
    console.print(f"  [cyan]→[/cyan] https://censys.io/ipv4/{ip_addr}")
    console.print(f"  [cyan]→[/cyan] https://www.virustotal.com/gui/ip-address/{ip_addr}")
    console.print(f"  [cyan]→[/cyan] https://ipinfo.io/{ip_addr}")
    console.print(f"  [cyan]→[/cyan] https://abuseipdb.com/check/{ip_addr}")

    # Reverse DNS
    console.print(f"\n[yellow][*] Reverse DNS...[/yellow]")
    try:
        import socket as _sock
        hostname = _sock.gethostbyaddr(ip_addr)[0]
        console.print(f"[green][+] Hostname: {hostname}[/green]")
    except Exception:
        console.print("[dim][-] لا يوجد PTR record[/dim]")

    # Save
    save = Prompt.ask("\n[pink1]حفظ النتائج؟ (y/n)[/pink1]", default="n")
    if save.lower() == "y" and results:
        lines = [
            f"VALLAINS OSINT — IP: {ip_addr}", "=" * 50, "",
            f"الدولة:  {results.get('country','')} ({results.get('countryCode','')})",
            f"المدينة: {results.get('city','')}",
            f"ISP:     {results.get('isp','')}",
            f"Proxy:   {'نعم' if results.get('proxy') else 'لا'}",
            f"الموقع:  {lat},{lon}",
            f"",
            f"Shodan:  https://www.shodan.io/host/{ip_addr}",
            f"Maps:    https://maps.google.com/?q={lat},{lon}",
        ]
        _save_results_to_file(f"osint_ip_{ip_addr.replace('.','_')}.txt", lines)


